local WuKongServerProvider = {}

local WuKongServer = nil
local WuKongHost = nil

function WuKongServerProvider.BuildWuKongServer(options: IWuKongOptions): IWuKongServer
	local optionsProvider = require(script.Parent.Parent.WuKongOptionsProvider)
	local defaultOptions = table.clone(optionsProvider.BuildDefaultOptions())

	if not options then
		options = {}
	end

	for k,v in options do
		defaultOptions[k] = v
	end

	if not WuKongHost then
		WuKongHost = _G.wdm.WuKong.RbxServer.WuKongServerHost(defaultOptions)
		WuKongServer = WuKongHost:Start()
	end

	local extensions = require(script.Parent.WuKongServerExtensions)

	for key, value in pairs(extensions) do
		WuKongServer[key] = value
	end

	return WuKongServer
end

function WuKongServerProvider.GetWuKongServer(): IWuKongServer
	assert(WuKongServer, "WuKongServer is not initialized")
	return WuKongServer
end

function WuKongServerProvider.Dispose()
	WuKongHost:Dispose()
	WuKongHost = nil
	WuKongServer = nil
end

return WuKongServerProvider
